import sys

def solve():
    N, M, K = map(int, sys.stdin.readline().split())
    X = list(map(int, sys.stdin.readline().split()))
    MOD = 998244353

    # Precompute nxt[j][c]
    # nxt[j][c] is the length of the longest prefix of X that is a subsequence of (X[0...j-1], c)
    nxt = [[0] * (K + 1) for _ in range(M)]
    for j in range(M):
        for c in range(1, K + 1):
            s = X[:j] + [c]
            curr = 0
            for char in s:
                if curr < M and char == X[curr]:
                    curr += 1
            nxt[j][c] = curr

    # dp[i][j] = number of sequences of length i with longest prefix of X length j
    dp = [[0] * M for _ in range(N + 1)]
    dp[0][0] = 1

    for i in range(N):
        for j in range(M):
            if dp[i][j] == 0:
                continue
            for c in range(1, K + 1):
                nj = nxt[j][c]
                if nj < M:
                    dp[i + 1][nj] = (dp[i + 1][nj] + dp[i][j]) % MOD

    # We need sequences that avoid X (state < M) and contain all other sequences of length M.
    # The condition implies we must reach state M-1.
    print(dp[N][M - 1])

