import sys

def solve():
    input = sys.stdin.read().split()
    if not input: return
    H, W = int(input[0]), int(input[1])
    F = []
    idx = 2
    for i in range(H):
        F.append([int(x) for x in input[idx:idx+W]])
        idx += W
    Q = int(input[idx])
    idx += 1

    edges = []
    for r in range(H):
        for c in range(W):
            if r + 1 < H:
                edges.append((min(F[r][c], F[r+1][c]), r*W + c, (r+1)*W + c))
            if c + 1 < W:
                edges.append((min(F[r][c], F[r][c+1]), r*W + c, r*W + c + 1))

    # Sort by floor capacity descending to use Kruskal's for max-bottleneck
    edges.sort(key=lambda x: x[0], reverse=True)

    parent = list(range(H * W))
    def find(i):
        if parent[i] == i: return i
        parent[i] = find(parent[i])
        return parent[i]

    # Kruskal's to find max bottleneck capacity between all pairs
    # Since H, W <= 500, we use a Disjoint Set Union
    # For each query, we need the bottleneck capacity between (A,B) and (C,D)
    # This is standard: the bottleneck is the min edge on the path in the MST
    adj = [[] for _ in range(H * W)]
    for w, u, v in edges:
        root_u, root_v = find(u), find(v)
        if root_u != root_v:
            parent[root_u] = root_v
            adj[u].append((v, w))
            adj[v].append((u, w))

    # LCA and Min Edge on path
    depth = [0] * (H * W)
    up = [[(-1, float('inf'))] * 20 for _ in range(H * W)]
    visited = [False] * (H * W)
    for i in range(H * W):
        if not visited[i]:
            stack = [(i, -1, 0, float('inf'))]
            while stack:
                u, p, d, w = stack.pop()
                visited[u] = True
                depth[u] = d
                up[u][0] = (p, w)
                for v, weight in adj[u]:
                    if v != p: stack.append((v, u, d + 1, weight))

    for j in range(1, 20):
        for i in range(H * W):
            mid, w1 = up[i][j-1]
            if mid != -1:
                end, w2 = up[mid][j-1]
                up[i][j] = (end, min(w1, w2))

    def get_bottleneck(u, v):
        if depth[u] < depth[v]: u, v = v, u
        res = float('inf')
        for j in range(19, -1, -1):
            if depth[u] - (1 << j) >= depth[v]:
                res = min(res, up[u][j][1])
                u = up[u][j][0]
        if u == v: return res
        for j in range(19, -1, -1):
            if up[u][j][0] != up[v][j][0]:
                res = min(res, up[u][j][1], up[v][j][1])
                u, v = up[u][j][0], up[v][j][0]
        return min(res, up[u][0][1], up[v][0][1])

    results = []
    for _ in range(Q):
        a, b, y, c, d, z = map(int, input[idx:idx+6])
        idx += 6
        u, v = (a-1)*W + (b-1), (c-1)*W + (d-1)
        if u == v:
            results.append(abs(y - z))
            continue
        bottleneck = get_bottleneck(u, v)
        target = min(y, z)
        if bottleneck >= target:
            results.append(abs(y - z))
        else:
            results.append(abs(y - bottleneck) + abs(bottleneck - z))

    sys.stdout.write('\n'.join(map(str, results)) + '\n')

