            pos[height] = []
        pos[height].append(i + 1)

    max_count = 1

    for height in pos:
        indices = pos[height]
        if len(indices) <= max_count:
            continue

        # Convert list to set for O(1) lookup
        idx_set = set(indices)

        # Try every pair (indices[i], indices[j]) as the first two elements
        m = len(indices)
        for i in range(m):
            for j in range(i + 1, m):
                diff = indices[j] - indices[i]
                count = 2
                current = indices[j]

                # Check how many more elements fit the progression
                while (current + diff) in idx_set:
                    count += 1
                    current += diff

                if count > max_count:
                    max_count = count

    print(max_count)

