import sys

def solve():
    A, B, M = map(int, sys.stdin.readline().split())
    N = A * B - 1

    memo_f = {}

    def get_f(partition):
        if partition in memo_f: return memo_f[partition]
        n = sum(partition)
        if n == 0: return 1
        res = 0
        for i in range(len(partition)):
            if partition[i] > 0:
                if i == 0 or partition[i] < partition[i-1]:
                    new_p = list(partition)
                    new_p[i] -= 1
                    res = (res + get_f(tuple(new_p))) % M
        memo_f[partition] = res
        return res

    # The condition implies we need to count SYT of shape lambda with lambda_1=A, lambda'_1=B
    # excluding those where no internal corner exists.
    # Actually, for a fixed shape lambda, there are (f^lambda)^2 permutations.
    # The condition "appending n+0.5" is satisfied if the shape lambda has at least one 
    # removable cell (r, c) such that r > 1 and c > 1.

    count = 0
    def generate_partitions(n, max_val, current_partition):
        nonlocal count
        if sum(current_partition) == n:
            if len(current_partition) == B and current_partition[0] == A:
                # Check if there is a corner (r, c) with r>1, c>1
                has_internal = False
                for i in range(1, len(current_partition)):
                    if current_partition[i] > 1:
                        has_internal = True
                        break
                if has_internal:
                    f = get_f(tuple(current_partition))
                    count = (count + f * f) % M
            return

        for val in range(min(max_val, n - sum(current_partition)), 0, -1):
            generate_partitions(n, val, current_partition + [val])

    generate_partitions(N, A, [])
    print(count)

