def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    s = [int(x) for x in input_data[1:]]

    max_s = 0
    for x in s:
        if x > max_s:
            max_s = x

    exists = [False] * (max_s + 1)
    for x in s:
        exists[x] = True

    count = 0
    # To optimize, we iterate over each B in S and check for symmetric pairs
    # The number of pairs is sum_{B in S} count_{k > 0} (B-k in S and B+k in S)
    for b in s:
        # We only need to check up to the smaller distance to the boundary
        limit = min(b - 1, max_s - b)
        for k in range(1, limit + 1):
            if exists[b - k] and exists[b + k]:
                count += 1

    print(count)

